{"command":"set -u
EVID="/home/vgpnk/Projects/shokunin/kumitate-shokunin/.ufo/waves/round-59/build/ExecCiteLive"
LANE="/home/vgpnk/Projects/shokunin/kumitate-shokunin"
cd "$LANE"

# secondary reading of the same file (not a substitute for the assigned git grep)
grep -n S121 -- corpus/README.md > "$EVID/grep-plain-s121.stdout" 2> "$EVID/grep-plain-s121.stderr"
printf '%s\n' "$?" > "$EVID/grep-plain-s121.exit"

# re-read cited count with the gate's published rule (script header + ID_RE)
node --input-type=module -e '
import { readFileSync } from "node:fs";
const readme = readFileSync("corpus/README.md", "utf8");
const sources = readFileSync("corpus/SOURCES.md", "utf8");
const ID_RE = /\bS[0-9]{3,}\b/g;
const ids = new Set();
for (const line of sources.split("\n")) {
  const m = line.match(/^ {0,3}\|\s*(S[0-9]{3,})\s*\|/);
  if (m) ids.add(m[1]);
}
const cited = [];
let mapRows = 0;
for (const line of readme.split("\n")) {
  if (!/^\s*\| /.test(line)) continue;
  mapRows++;
  const found = line.match(ID_RE);
  if (found) cited.push(...found);
}
const ghosts = [];
const seen = new Set();
for (const id of cited) {
  if (ids.has(id) || seen.has(id)) continue;
  seen.add(id);
  ghosts.push(id);
}
const line = `recount cited=${cited.length} mapRows=${mapRows} registryIds=${ids.size} ghosts=${ghosts.length} first=${ghosts[0] ?? "none"} s121cited=${cited.includes("S121")} s121registry=${ids.has("S121")}`;
process.stdout.write(line + "\n");
process.exit(ghosts.length ? 1 : 0);
' > "$EVID/recount.stdout" 2> "$EVID/recount.stderr"
printf '%s\n' "$?" > "$EVID/recount.exit"

# local git-grep exit-status wording, if the installed help contains it
git help grep > "$EVID/git-help-grep.stdout" 2> "$EVID/git-help-grep.stderr" || true
printf '%s\n' "$?" > "$EVID/git-help-grep.exit"
grep -n -i -E 'exit status|no match|Exit' "$EVID/git-help-grep.stdout" > "$EVID/git-help-grep-exit-lines.txt" || true

printf 'plain.exit=%s bytes=%s\n' "$(cat "$EVID/grep-plain-s121.exit")" "$(wc -c < "$EVID/grep-plain-s121.stdout")"
printf 'recount.exit=%s\n' "$(cat "$EVID/recount.exit")"
cat "$EVID/recount.stdout"
printf 'help-exit-lines:\n'
cat "$EVID/git-help-grep-exit-lines.txt"
printf 'date:\n'
cat "$EVID/date.stdout"
printf 'diff.exit=%s status.exit=%s ancestor.exit=%s\n' "$(cat "$EVID/diff-score-gate-inputs.exit")" "$(cat "$EVID/status-gate-inputs.exit")" "$(cat "$EVID/score-ancestor.exit")"
printf 'fleet-cwd:\n'
cat "$EVID/cite-sources-fleet-cwd.stdout"
printf 'fleet-exit=%s\n' "$(cat "$EVID/cite-sources-fleet-cwd.exit")"","description":"Recount citations and quote git-grep exit docs"}
